SELECT ct.id, ct.display_name AS NAME, ct.customer_id, ct.display_number AS number, ct.customer_name_snapshot, ct.customer_mobile_snapshot, ct.customer_source_snapshot, ct.owner_name_snapshot, ct.display_signer_id AS signer_id, ct.display_signer_name AS signer_name_snapshot, ct.display_signer_dept_id AS signer_dept_id_snapshot, ct.display_signer_dept_name AS signer_dept_name_snapshot, ct.display_expected_repayment_amount AS expected_repayment_amount, ct.effective_version_id, ct.pending_version_id, ct.lock_version, c.in_shared_pool AS inCustomerPool, c.pool_id, ct.display_amount AS amount, ct.approval_status, ct.display_stage AS stage, ct.`owner`, ct.display_start_time AS start_time, ct.display_end_time AS end_time, ct.void_reason, ct.create_user, ct.create_time, ct.update_user, ct.update_time, ct.alreadyPayAmount FROM ( SELECT ctt.*, IFNULL(SUM(cpr.record_amount), 0) AS alreadyPayAmount, display_version.value_snapshot AS display_value_snapshot, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.name')), ctt.name) AS display_name, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.number')), ctt.number) AS display_number, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.signerId')), ctt.signer_id) AS display_signer_id, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.signerNameSnapshot')), ctt.signer_name_snapshot) AS display_signer_name, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.signerDeptIdSnapshot')), ctt.signer_dept_id_snapshot) AS display_signer_dept_id, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.signerDeptNameSnapshot')), ctt.signer_dept_name_snapshot) AS display_signer_dept_name, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.amount') + 0, ctt.amount) AS display_amount, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.expectedRepaymentAmount') + 0, ctt.expected_repayment_amount) AS display_expected_repayment_amount, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.startTime') + 0, ctt.start_time) AS display_start_time, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.endTime') + 0, ctt.end_time) AS display_end_time, IF(display_version.id IS NOT NULL, 'PENDING_SIGNING', ctt.stage) AS display_stage FROM contract ctt LEFT JOIN contract_version display_version ON display_version.id = COALESCE( ctt.pending_version_id, CASE WHEN ctt.effective_version_id IS NULL THEN ( SELECT latest_version.id FROM contract_version latest_version WHERE latest_version.contract_id = ctt.id ORDER BY latest_version.version_no DESC LIMIT 1 ) END ) LEFT JOIN contract_payment_record cpr on cpr.contract_id = ctt.id AND cpr.approval_status = 'APPROVED' AND cpr.effective_version_id IS NOT NULL GROUP BY ctt.id ) ct LEFT JOIN customer c ON ct.customer_id = c.id
join sys_organization_user on ct.owner = sys_organization_user.user_id and ( sys_organization_user.department_id in
#{deptId}
or sys_organization_user.user_id = #{userId}
)
where ct.organization_id = #{orgId}
and ct.customer_id = #{request.customerId}
and ct.signer_id = #{userId}
and ct.owner = #{userId}
and ( ct.display_name like concat('%', #{request.keyword},'%') or c.name like concat('%', #{request.keyword},'%') )
and ct.display_name like concat('%', #{request.keyword},'%')

SELECT ct.id, ct.NAME, ct.customer_id, ct.customer_name_snapshot, ct.customer_mobile_snapshot, ct.customer_source_snapshot, ct.owner_name_snapshot, ct.signer_id, ct.signer_name_snapshot, ct.signer_dept_id_snapshot, ct.signer_dept_name_snapshot, ct.expected_repayment_amount, ct.effective_version_id, ct.pending_version_id, ct.lock_version, c.in_shared_pool AS inCustomerPool, c.pool_id, ct.amount, ct.number, ct.approval_status, ct.stage, ct.`owner`, ct.void_reason, ct.create_user, ct.create_time, ct.update_user, ct.update_time, ct.start_time, ct.end_time, ct.alreadyPayAmount FROM ( SELECT ctt.*, IFNULL(SUM(cpr.record_amount), 0) AS alreadyPayAmount FROM contract ctt LEFT JOIN contract_payment_record cpr on cpr.contract_id = ctt.id AND cpr.approval_status = 'APPROVED' AND cpr.effective_version_id IS NOT NULL GROUP BY ctt.id ) ct LEFT JOIN customer c ON ct.customer_id = c.id
join sys_organization_user on ct.owner = sys_organization_user.user_id and ( sys_organization_user.department_id in
#{deptId}
)
where ct.organization_id = #{orgId} and ct.id in
#{id}
and ct.owner = #{userId}

foreach.if:
left join JSON_TABLE(
    COALESCE(JSON_EXTRACT(ct.display_value_snapshot, '$.moduleFields'), JSON_ARRAY()),
    '$[*]' COLUMNS(
        field_id VARCHAR(255) PATH '$.fieldId',
        field_value VARCHAR(4000) PATH '$.fieldValue' NULL ON EMPTY
    )
) ${tablePrefix}_version_${i}
on ${tablePrefix}_version_${i}.field_id = #{condition.name}

    left join contract_field_blob ${tablePrefix}_${i}
    on ct.id = ${tablePrefix}_${i}.resource_id and ${tablePrefix}_${i}.field_id = #{condition.name}


    left join contract_field ${tablePrefix}_${i}
    on ct.id = ${tablePrefix}_${i}.resource_id and ${tablePrefix}_${i}.field_id = #{condition.name}

sql.if:

left join contract_field sort_table
on ct.id = sort_table.resource_id and sort_table.field_id = #{sortName}
left join JSON_TABLE(
    COALESCE(JSON_EXTRACT(ct.display_value_snapshot, '$.moduleFields'), JSON_ARRAY()),
    '$[*]' COLUMNS(
        field_id VARCHAR(255) PATH '$.fieldId',
        field_value VARCHAR(4000) PATH '$.fieldValue' NULL ON EMPTY
    )
) sort_version_table on sort_version_table.field_id = #{sortName}
left join sys_module_field module_table on module_table.id = #{sortName}

