SELECT
IFNULL(SUM(ct.amount), 0) as totalAmount
FROM
contract ct
LEFT JOIN customer c ON ct.customer_id = c.id

    join sys_organization_user on ct.owner = sys_organization_user.user_id
    and (
    sys_organization_user.department_id in

        #{deptId}

    )

where ct.organization_id = #{orgId} and ct.customer_id = #{customerId}

    and ct.owner = #{userId}

select id from contract
where id in

    #{id}

and approval_status = #{approvalStatus}

select *
from contract
where organization_id = #{organizationId}
  and end_time >= #{timestampOld}
  and end_time < #{timestamp}
  and stage!='VOID' and stage!='COMPLETED_PERFORMANCE'

mapper.update:
update contract
set approval_status = #{approvalStatus},
    update_user     = #{userId},
    update_time     = #{updateTime}
where id = #{id}

update contract
set stage       = #{stage},
    update_user = #{userId},
    update_time = #{updateTime}
where id = #{id}

mapper.select:
SELECT *
FROM contract
WHERE id = #{id}
  AND organization_id = #{orgId}
FOR UPDATE

SELECT sum(ct.display_amount) as amount, sum(ct.display_amount) / count(*) as averageAmount FROM ( SELECT ctt.*, display_version.value_snapshot AS display_value_snapshot, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.name')), ctt.name) AS display_name, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.number')), ctt.number) AS display_number, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.signerId')), ctt.signer_id) AS display_signer_id, COALESCE(JSON_UNQUOTE(JSON_EXTRACT(display_version.value_snapshot, '$.signerDeptIdSnapshot')), ctt.signer_dept_id_snapshot) AS display_signer_dept_id, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.amount') + 0, ctt.amount) AS display_amount, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.startTime') + 0, ctt.start_time) AS display_start_time, COALESCE(JSON_EXTRACT(display_version.value_snapshot, '$.endTime') + 0, ctt.end_time) AS display_end_time, IF(display_version.id IS NOT NULL, 'PENDING_SIGNING', ctt.stage) AS display_stage, COALESCE(payment_amount.alreadyPayAmount, 0) AS alreadyPayAmount FROM contract ctt LEFT JOIN contract_version display_version ON display_version.id = COALESCE( ctt.pending_version_id, CASE WHEN ctt.effective_version_id IS NULL THEN ( SELECT latest_version.id FROM contract_version latest_version WHERE latest_version.contract_id = ctt.id ORDER BY latest_version.version_no DESC LIMIT 1 ) END ) LEFT JOIN ( SELECT contract_id, SUM(record_amount) AS alreadyPayAmount FROM contract_payment_record GROUP BY contract_id ) payment_amount ON payment_amount.contract_id = ctt.id ) ct LEFT JOIN customer c ON ct.customer_id = c.id
join sys_organization_user on ct.owner = sys_organization_user.user_id and ( sys_organization_user.department_id in
#{deptId}
or sys_organization_user.user_id = #{userId}
)
where ct.organization_id = #{orgId}
and ct.owner = #{userId}
and ( ct.display_name like concat('%', #{request.keyword},'%') )

